#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"//int downdelta; //смещение соответствующее зачению управлюемой переменной на момент нажатия мышиRECT StartRect;RECT ForInvalidateRect;RECT ForCheckPointRect; //тоже что ForInvalidateRect но с запасом - для проверки мыши над диазоном перемещений слайдераstatic void DrawSlider(HWND hWnd){    if ( (!QueueWndMouseState.SliderBmp) || (QueueWndMouseState.hWnd != hWnd) || (!::IsWindow(hWnd)) ) return;  //  if(!::PtInRect(&ForCheckPointRect, QueueWndMouseState.CurrentPoint))  {       QueueWndMouseState.bMouseDown = false;       QueueWndMouseState.SliderBmp = NULL;       QueueWndMouseState.hWnd = NULL;       return;  }  //  ::InvalidateRect( hWnd, &ForInvalidateRect, FALSE );  //  HDC hDC = ::GetDC(hWnd);  Graphics gr( hDC );  SIZE sz = {QueueWndMouseState.SliderBmp->GetWidth(), QueueWndMouseState.SliderBmp->GetHeight()};  int delta = QueueWndMouseState.CurrentPoint.y - QueueWndMouseState.DownPoint.y + downdelta;  if(delta>0)     delta = 0;  else if(delta < -QueueWndMouseState.MaxDelta)         delta = -QueueWndMouseState.MaxDelta;  gr.DrawImage(QueueWndMouseState.SliderBmp, StartRect.left, StartRect.top + delta, sz.cx, sz.cy );  ::ReleaseDC(hWnd, hDC );}////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nKlapan;  bool bZadanie;  Bitmap* bmp;  int StartPos;  bool bMouseDown;  RECT CurrentRect;  double WorkMin; //мин источника   double WorkMax; //мах источника  int    MaxDelta; //максимальное смещение для мах SourseMax  } Queue_Slider;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearSlider(SQueue& q,void* s)  {  Queue_Slider* p = (Queue_Slider*)s;  if(p->bmp)    delete p->bmp;  p->bmp = NULL;  QueueWndMouseState.bMouseDown = false;  QueueWndMouseState.SliderBmp = NULL;  QueueWndMouseState.hWnd = NULL;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintSlider(DefinePaint)  {  QueueP(Queue_Slider);  //  if(!p->bmp)    return 1;  //  RECT rc = p->mRect;  int delta = 0;     //смещение по которому рисуем  int valuedelta = 0; //смещение соответствующее текущему зачению управлюемой переменной   double dValue =0;  bool bNeedSendNewValue = false;  bool bManual = false;  if (p->nKlapan >= 0)	{		CShKlapan* sh = (CShKlapan*)q.m_pPipe->Sh(p->nKlapan);		if ( IsTypeOk )		{			if (p->bZadanie)				dValue=sh->VentZ;			else				dValue=sh->Vent_Dubler;            //bManual=(sh->LocalRemoteDouble==0);            if(dValue > p->WorkMax)              dValue = p->WorkMax;            else if(dValue < p->WorkMin)                   dValue = p->WorkMin;            valuedelta =  -int(p->MaxDelta*(dValue - p->WorkMin)/(p->WorkMax - p->WorkMin));            if(!p->bMouseDown)            {            delta = valuedelta;            p->CurrentRect = rc;            ::OffsetRect( &p->CurrentRect, 0, delta);            ::InflateRect(&p->CurrentRect, 10, 80); //расшерен, что при даижении мыши случайно не выходило за пределы            }		}	}  if(q.hWnd == QueueWndMouseState.hWnd)  {    if(::PtInRect(&p->CurrentRect, QueueWndMouseState.CurrentPoint))    {        if(QueueWndMouseState.bMouseDown && !bManual)        {            if(!p->bMouseDown)            {              p->StartPos=QueueWndMouseState.DownPoint.y;              StartRect = p->mRect;              downdelta = valuedelta;              QueueWndMouseState.SliderBmp = p->bmp;              QueueWndMouseState.pDrawSlider = DrawSlider;              ForInvalidateRect.left = StartRect.left - 2;              ForInvalidateRect.right = StartRect.right + 2;              ForInvalidateRect.top = StartRect.top - p->MaxDelta - 2;              ForInvalidateRect.bottom = StartRect.bottom + 2;              ForCheckPointRect = ForInvalidateRect;              ::InflateRect(&ForCheckPointRect, 10, 80);             }            p->bMouseDown = true;            QueueWndMouseState.MaxDelta = p->MaxDelta;            delta = QueueWndMouseState.CurrentPoint.y - QueueWndMouseState.DownPoint.y + valuedelta;            if(delta>0)               delta = 0;            else if(delta < -p->MaxDelta)                   delta = -p->MaxDelta;            p->CurrentRect = rc;            ::OffsetRect( &p->CurrentRect, 0, delta);            ::InflateRect(&p->CurrentRect, 30, 90); //расшерен, что при даижении мыши случайно не выходило за пределы                    QueueWndMouseState.SliderBmp = p->bmp;              Graphics gr( hDC );            SIZE sz = {QueueWndMouseState.SliderBmp->GetWidth(), QueueWndMouseState.SliderBmp->GetHeight()};            gr.DrawImage(QueueWndMouseState.SliderBmp, StartRect.left, StartRect.top + delta, sz.cx, sz.cy );            return 1;        }        else        {           if(p->bMouseDown)             bNeedSendNewValue=true;            p->bMouseDown = false;        }    }    else    {         //if(p->bMouseDown)       //  bNeedSendNewValue=true;       delta = valuedelta;       p->bMouseDown = false;       p->CurrentRect = rc;          QueueWndMouseState.SliderBmp = NULL;       QueueWndMouseState.hWnd = NULL;    }    //    if(bNeedSendNewValue)      {      SSendToModel send;	  if (p->bZadanie)	   lstrcpy( send.szValue, "Задание" );	  else	   lstrcpy( send.szValue, "Дубл¸р" );		  // Имя переменной      delta = QueueWndMouseState.UpPoint.y - QueueWndMouseState.DownPoint.y + downdelta;      if(delta >0)        delta =0;      double dNew = p->WorkMin - (p->WorkMax-p->WorkMin)*delta/p->MaxDelta;      if(dNew > p->WorkMax)        dNew = p->WorkMax;	   send.Set( enumValueDbl, &dValue, &dNew );	   q.m_pPipe->SendData( p->nKlapan, send );      }    }  else  {       p->bMouseDown = false;  }  //  Graphics gr( hDC );  SIZE sz = {p->bmp->GetWidth(),p->bmp->GetHeight()};  gr.DrawImage( p->bmp, rc.left,  rc.top + delta, sz.cx, sz.cy );  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddSlider(DefineTegs)  {  char szExt  [_MAX_EXT  ];  char szPath [_MAX_PATH ];  char szFile [_MAX_FNAME];  wchar_t wPath[_MAX_PATH];  //  _splitpath_s( teg[0].value, 0,0, 0,0, 0,0, szExt, _MAX_EXT );  lstrcpy( szFile, teg[0].value );  if ( !*szExt ) lstrcat( szFile, ".png" );  GetPathScn( szPath, szFile, false );  //  NetworkFile( szPath );  //  MultiByteToWideChar(CP_ACP, 0, szPath, -1, wPath, _MAX_PATH);  Bitmap* bmp = Bitmap::FromFile( wPath );  if ( bmp == NULL ) return;  //  AddQueueEx(Queue_Slider);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintSlider;  p->clear = &ClearSlider;  //  p->bmp = bmp;  EDirect eDir = dirUp;  //  p->bMouseDown = false;  p->StartPos=0;  char szKlapan[64] = "";  char szSFcom[64] = "";  p->nKlapan=-1;  p->WorkMin=0;  p->WorkMax=100;  //  STegObj obj[] =    {    { 'R', "rect" , &p->mRect },    { 'E', "rc"   , &p->mRect },    { 'N', "d"     , &eDir },    { 'N', "dir"   , &eDir },    { 'N', "direct", &eDir },    { 'D', "soursemin" ,  &p->WorkMin },    { 'D', "soursemax" ,  &p->WorkMax },    { 'S', "viewKlapan", szKlapan, 63 },    { 'L', "zadanie", &p->bZadanie },    { 'I', "max" , &p->MaxDelta },    { 'S', "suffcommon", szSFcom, 63 },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  if(p->MaxDelta == 0)    p->MaxDelta = 1;  //  if ( *szKlapan )  {		p->nKlapan = def.AddKind(id_Klapan, szKlapan);  }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~